/// <summary>
/// Override error correction methods. Used for substitutes.
/// </summary>
/// <param name = "_method">_method</param>
public void metOverrideErrorCorrectionMethods(InventMovementQuantityErrorCorrectionMethod _method)
{
    this.lowerLimitErrorCorrectionMethod    = _method;
    this.upperLimitErrorCorrectionMethod    = _method;
    this.multiplicityErrorCorrectionMethod  = _method;
}

    /// <summary>
    /// CB166_SalesOrderSubstitutes Apply minimum & multiple quantities from default order settings
    /// Out of the box finds the sales unit from InventTableModule
    /// Extension to retrieve it from new custom field METSalesUnit InventItemSalesSetup if configured
    /// </summary>
    /// <returns>Default order settings sales unit if found; otherwise, released product sales unit</returns>
    protected UnitOfMeasureSymbol moduleUnitId()
    {
        UnitOfMeasureSymbol	metModuleUnitId;
        
        metModuleUnitId = next moduleUnitId();

        // only for InventItemSalesSetup
        if (inventItemOrderSetupMap.setupType() == InventItemOrderSetupType::Sales)
        {
            // search site specific default order settings. Site or blank
            InventItemSalesSetup inventItemSalesSetup = InventItemSalesSetup::find(inventItemOrderSetupMap.itemId, inventItemOrderSetupMap.inventDimId);

            if (inventItemSalesSetup && inventItemSalesSetup.METSalesUnit)
            {
                metModuleUnitId = inventItemSalesSetup.METSalesUnit;
            }            
        }

        return metModuleUnitId;
    }
